/**
 * JSON Feed, as generated by `@indiekit/endpoint-json-feed`
 * @see {@link https://jsonfeed.org/version/1.1}
 */
interface JsonFeed {
  /** Format version URL */
  version: string;
  /** Feed name */
  title: string;
  /** URL of the website the feed describes */
  home_page_url: string;
  /** Feed URL */
  feed_url: string;
  /** Primary language of the feed */
  language: string;
  items: JsonFeedItem[];
}

interface JsonFeedItem {
  /** Unique ID */
  id: string;
  url: string;
  date_published: string;
  title?: string;
  summary?: string;
  /** Item content as HTML */
  content_html?: string;
  /** Item content as plain text */
  content_text?: string;
  tags?: string[];
  /** URL of the page the item is about */
  external_url?: string;
  /** Related resources */
  attachments?: JsonFeedAttachment[];
}

interface JsonFeedAttachment {
  url: string;
  /** Attachment name */
  title?: string;
  /** Attachment type, or `false` if `mime-types` can’t find one for the URL */
  mime_type: string | false;
}
